-- Lettres accentuées de l'espéranto écrites en deux caractères : lettre de base + accent combinant
-- (circonflexe U+0302, brève U+0306), par ex. g + ̂ au lieu de ĝ (U+011D). Elles s'affichent bien, mais la
-- recherche et la comparaison de texte ne les reconnaissent pas. Remplacées par les caractères précomposés
-- (ĉ ĝ ĥ ĵ ŝ ŭ et majuscules) : cours élémentaire (pages 1.4, 2.1, 2.3, 4.8, 6.7, 6.9), Pasoj al plena posedo
-- (pages 7.2 à 12.2, textes collés depuis une source qui écrivait les accents à part), consignes et questions
-- de quelques exercices. Seules ces douze combinaisons sont touchées. Script rejouable.
SET NAMES utf8mb4;
UPDATE lecioneroj SET enhavo = REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(REPLACE(enhavo, CONVERT(X'63CC82' USING utf8mb4), CONVERT(X'C489' USING utf8mb4)), CONVERT(X'43CC82' USING utf8mb4), CONVERT(X'C488' USING utf8mb4)), CONVERT(X'67CC82' USING utf8mb4), CONVERT(X'C49D' USING utf8mb4)), CONVERT(X'47CC82' USING utf8mb4), CONVERT(X'C49C' USING utf8mb4)), CONVERT(X'68CC82' USING utf8mb4), CONVERT(X'C4A5' USING utf8mb4)), CONVERT(X'48CC82' USING utf8mb4), CONVERT(X'C4A4' USING utf8mb4)), CONVERT(X'6ACC82' USING utf8mb4), CONVERT(X'C4B5' USING utf8mb4)), CONVERT(X'4ACC82' USING utf8mb4), CONVERT(X'C4B4' USING utf8mb4)), CONVERT(X'73CC82' USING utf8mb4), CONVERT(X'C59D' USING utf8mb4)), CONVERT(X'53CC82' USING utf8mb4), CONVERT(X'C59C' USING utf8mb4)), CONVERT(X'75CC86' USING utf8mb4), CONVERT(X'C5AD' USING utf8mb4)), CONVERT(X'55CC86' USING utf8mb4), CONVERT(X'C5AC' USING utf8mb4))
WHERE (enhavo LIKE BINARY CONCAT('%', CONVERT(X'CC82' USING utf8mb4), '%') OR enhavo LIKE BINARY CONCAT('%', CONVERT(X'CC86' USING utf8mb4), '%'));
